const T=api.THREE, nb=8, buyers=[], sellers=[];
for(let i=0;i<nb;i++){ const b=api.body('b'+i), s=api.body('s'+i); buyers.push({o:b,z0:b.position.z}); sellers.push({o:s,z0:s.position.z}); }
const coin=api.body('price'); let p=1.5, last=0;
